    if len(cs)==1: return ('v',len(cells))
    return None

def has_line(cells, orient, length):
    coords=set(cells)
    if orient=='h':
        byrow={}
        for r,c in coords: byrow.setdefault(r,set()).add(c)
        return any(any(all(c0+i in cols for i in range(length)) for c0 in cols) for cols in byrow.values())
    bycol={}
    for r,c in coords: bycol.setdefault(c,set()).add(r)
